"""Give the FirstRun homepage life: full-bleed film, open numbers, PR shelf, ledgers, plan track,
open compare, race-track build log, soft depth and fluid reveal. Nav and section flow stay."""
import re, sys
p = sys.argv[1]
track_js = open(sys.argv[2], encoding="utf-8").read()
s = open(p, encoding="utf-8").read()


def rep(old, new, n=1):
    global s
    assert s.count(old) == n, (s.count(old), old[:100])
    s = s.replace(old, new)


def between(a, b):
    i = s.index(a); j = s.index(b, i) + len(b)
    return i, j


def ic(name, extra=""):
    return f'<svg class="ic"{extra} aria-hidden="true"><use href="#{name}"/></svg>'


# ---------------------------------------------------------------- head: js flag for reveal
rep('<meta name="color-scheme" content="light">',
    '<meta name="color-scheme" content="light">\n<script>document.documentElement.className="js"</script>')

# ---------------------------------------------------------------- tokens: depth, ease, air
rep('--sh:0 1px 2px oklch(30% .02 255/.06);',
    '--sh:0 1px 2px oklch(30% .02 255/.06);\n'
    '--lift:0 1px 2px oklch(30% .03 256/.05),0 8px 24px -10px oklch(35% .06 256/.16),0 24px 56px -28px oklch(35% .06 256/.18);\n'
    '--lift-h:0 2px 4px oklch(30% .03 256/.06),0 16px 36px -12px oklch(35% .07 256/.22),0 36px 72px -30px oklch(35% .07 256/.24);\n'
    '--ease:cubic-bezier(.16,1,.3,1);--road:oklch(22% .012 255/.08);')
rep('--pad:clamp(44px,6vw,72px)}', '--pad:clamp(64px,9vw,120px)}')
rep('.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;box-shadow:var(--sh)}',
    '.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:var(--lift)}\n'
    '/* motion: one fade and rise as a block enters, staggered inside a group */\n'
    'html.js .rv{opacity:0;transform:translateY(22px);transition:opacity .9s var(--ease),transform .9s var(--ease)}\n'
    'html.js .rv.in{opacity:1;transform:none}\n'
    '.app,.tool,.pr,.shots figure,.anno figure{transition:transform .6s var(--ease),box-shadow .6s var(--ease),border-color .2s}\n'
    '.app:hover,.tool:hover,.pr:hover,.shots figure:hover{transform:translateY(-4px);box-shadow:var(--lift-h)}')

# ---------------------------------------------------------------- hero: a soft glow behind the hero only
rep('#hero{text-align:center;padding-top:clamp(20px,4vw,44px)}',
    '#hero{text-align:center;padding-top:clamp(28px,5vw,64px);position:relative;isolation:isolate}\n'
    '#hero:before{content:"";position:absolute;z-index:-1;left:50%;top:-140px;width:min(1400px,140vw);height:760px;transform:translateX(-50%);pointer-events:none;'
    'background:radial-gradient(34% 42% at 28% 34%,oklch(84% .09 256/.42),transparent 72%),radial-gradient(30% 38% at 74% 28%,oklch(84% .1 295/.34),transparent 72%),'
    'radial-gradient(28% 34% at 52% 78%,oklch(90% .08 150/.30),transparent 72%)}\n'
    '#hero>*{animation:rise 1s var(--ease) both}#hero>:nth-child(2){animation-delay:.06s}#hero>:nth-child(3){animation-delay:.12s}#hero>:nth-child(4){animation-delay:.18s}#hero>:nth-child(n+5){animation-delay:.24s}\n'
    '@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}')
rep('.box{display:flex;gap:8px;align-items:center;margin:24px auto 0;max-width:620px;border-radius:14px;padding:6px 6px 6px 18px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--sh)}',
    '.box{display:flex;gap:8px;align-items:center;margin:28px auto 0;max-width:640px;border-radius:16px;padding:7px 7px 7px 20px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--lift)}')
rep('.apps{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:22px;text-align:left}',
    '.apps{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:40px;text-align:left}')

# ---------------------------------------------------------------- film: full bleed, edges fade into the page
i, j = between('<figure class="film card" id="film">', '</figure>\n')
s = s[:i] + s[j:]
film = ('<section id="film" class="film" aria-label="Launch film">\n<div class="reel rv">\n'
        '<video id="reel" muted loop playsinline preload="metadata" poster="assets/launch-poster.jpg" aria-label="FirstRun launch film, 44 seconds, plays silently on a loop">'
        '<source src="assets/firstrun-launch.mp4" type="video/mp4"></video>\n'
        '<div class="ctl"><button type="button" id="pp">Pause</button><button type="button" id="mu">Sound on</button></div>\n</div>\n</section>\n\n')
rep('<section id="steps" aria-labelledby="steps-h">', film + '<section id="steps" aria-labelledby="steps-h">')
for old in ('.film{margin-top:26px;overflow:hidden}\n', '.film video{display:block;width:100%;aspect-ratio:2/1;object-fit:cover;background:var(--sunk)}\n',
            '.film p{padding:10px 14px;font-size:13.5px;color:var(--mut)}\n'):
    rep(old, '')
MASK = 'linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent),linear-gradient(180deg,transparent,#000 11%,#000 89%,transparent)'
film_css = ('/* film: full bleed, no frame, edges fade into the page */\n'
            '#film{max-width:none;padding:clamp(32px,5vw,72px) 0 0}\n'
            '.reel{position:relative;max-width:1680px;margin:0 auto;aspect-ratio:2/1}\n'
            f'.reel video{{display:block;width:100%;height:100%;object-fit:cover;background:var(--bg);-webkit-mask-image:{MASK};-webkit-mask-composite:source-in;mask-image:{MASK};mask-composite:intersect;mix-blend-mode:multiply}}\n'
            '.ctl{position:absolute;right:max(20px,8%);bottom:9%;display:flex;gap:8px}\n'
            '.ctl button{min-height:36px;padding:0 16px;font-size:13px;color:var(--ink);background:oklch(99.7% .0015 255/.9);border:1px solid var(--line);box-shadow:var(--lift)}\n'
            '.ctl button:hover{background:var(--panel)}\n')
rep('/* proof */', film_css + '\n/* proof */')

# ---------------------------------------------------------------- proof: open numbers, PR shelf, two ledgers
i, j = between('<div class="stats">', '<a class="more" href="doc-audit/" style="color:var(--audit)">Open Doc-audit</a>\n</div>\n')
PR = [
    ("dbt-labs/docs.getdbt.com", "10149", "dbt-labs", "Fix the jafgen command", "doc-test/?s=10#ex=dbt",
     '<code>jafgen --years 6</code> fails with <code>No such option: --years</code>.',
     "Screenshot of pull request 10149 on dbt-labs/docs.getdbt.com, fixing the jafgen command in the DuckDB quickstart"),
    ("dbt-labs/docs.getdbt.com", "10150", "dbt-labs", "State the Python version", "doc-test/?s=3#ex=dbt",
     'The repo pins <code>networkx==3.7</code>, which needs Python 3.12.',
     "Screenshot of pull request 10150 on dbt-labs/docs.getdbt.com, stating the Python version the quickstart needs"),
    ("entireio/cli", "2724", "entireio", "Say where install.sh puts entire", "doc-test/?s=2#ex=entire",
     'After a good install, <code>entire version</code> says <code>command not found</code>.',
     "Screenshot of pull request 2724 on entireio/cli, saying where install.sh puts entire on Linux"),
    ("accuknox/help", "671", "accuknox", "Point knoxctl at the latest release", "doc-test/?s=2#ex=accuknox",
     'The page names 0.9.0 as latest. The installer already fetches 0.9.58.',
     "Screenshot of pull request 671 on accuknox/help, pointing knoxctl at the latest release"),
]
cards = ""
for repo, n, org, title, replay, broke, alt in PR:
    gh = f"https://github.com/{repo}/pull/{n}"
    cards += (f'<article class="pr card" data-repo="{repo}" data-n="{n}">'
              f'<a class="shot" href="{gh}" target="_blank" rel="noopener" tabindex="-1"><img src="assets/pr-{n}.webp" alt="{alt}" width="1200" height="668" loading="lazy"></a>'
              f'<div class="pr-b"><div class="pr-top"><img src="https://github.com/{org}.png?size=52" alt="" width="26" height="26" loading="lazy">'
              f'<span class="repo">{repo}</span><span class="st">Open</span></div>'
              f'<a class="t" href="{gh}" target="_blank" rel="noopener">{title} <small>#{n}</small></a>'
              f'<p class="br"><b>Broke</b>{broke}</p>'
              f'<div class="pr-a"><a class="rp" href="{replay}">{ic("i-play")}Replay the fix</a><a class="gh" href="{gh}" target="_blank" rel="noopener">GitHub &#8599;</a></div></div></article>\n')


def fig(cls, idv, val, label):
    ida = f' id="{idv}"' if idv else ""
    return f'<div><b class="cu {cls}"{ida}>{val}</b><span>{label}</span></div>'


proof = (
    '<div class="figs rv">\n'
    f'<div class="fg"><p class="k">{ic("i-term")}Doc-test</p><div class="fn">{fig("g","s-fix","16","pages with a fix proven")}{fig("bl","s-ok","8","docs that work as written")}</div></div>\n'
    f'<div class="fg"><p class="k">{ic("i-pr")}Upstream</p><div class="fn">{fig("","","4","docs PRs opened")}</div></div>\n'
    f'<div class="fg"><p class="k">{ic("i-audit")}Doc-audit</p><div class="fn">{fig("v","s-rep","4","repos audited")}{fig("v","s-stale","15","stale pages found")}</div></div>\n'
    f'<div class="fg"><p class="k">{ic("i-gauge")}neatlogs</p><div class="fn">{fig("","","$0.02","model cost per run")}</div></div>\n'
    '</div>\n\n'
    f'<div class="shelf-h" id="prs"><h3>{ic("i-pr")}Four upstream docs PRs, all open</h3>'
    '<div class="arws"><button type="button" class="arw" id="prP" aria-label="Previous pull request">&lsaquo;</button>'
    '<button type="button" class="arw" id="prN" aria-label="Next pull request">&rsaquo;</button></div></div>\n'
    '<div class="shelf" id="shelf" tabindex="0" role="region" aria-label="Upstream pull requests">\n' + cards + '</div>\n'
    '<a class="more" href="https://entire.io/gh/HighnessAtharva/firstrun/session/ae05fb29-0c85-4558-9980-42419f08ca9c" target="_blank" rel="noopener">See the Entire session that ran all four &rarr;</a>\n\n'
    '<div class="ledgers">\n'
    '<div class="ledger card rv"><div class="lg-h"><span class="app-i" style="background:var(--test)">' + ic("i-term") + '</span><b>Doc-test replays</b>'
    '<span class="lgd"><i style="background:var(--ok)"></i>Fix proven</span><span class="lgd"><i style="background:var(--test)"></i>Docs work</span></div>\n'
    '<div class="rows" id="replays">'
    '<a class="lr g" href="doc-test/#ex=dbt">' + ic("i-check") + '<b>dbt + DuckDB quickstart</b><span>fix proven</span><i aria-hidden="true">&rarr;</i></a>'
    '<a class="lr g" href="doc-test/#ex=entire">' + ic("i-check") + '<b>Entire CLI install</b><span>fix proven</span><i aria-hidden="true">&rarr;</i></a>'
    '</div>\n<a class="more" href="doc-test/">Open Doc-test &rarr;</a></div>\n'
    '<div class="ledger card rv"><div class="lg-h"><span class="app-i" style="background:var(--audit)">' + ic("i-audit") + '</span><b>Doc-audit reports</b></div>\n'
    '<div class="rows" id="audits">'
    '<a class="lr v" href="doc-audit/?id=audit-20261010-163620-dbt-labs-dbt-core">' + ic("i-list") + '<b>dbt-labs/dbt-core</b><span>15 stale of 1405</span><i aria-hidden="true">&rarr;</i></a>'
    '</div>\n<a class="more" href="doc-audit/" style="color:var(--audit)">Open Doc-audit &rarr;</a></div>\n'
    '</div>\n')
s = s[:i] + proof + s[j:]

# the row builder writes ledger rows now
rep(' var a=document.createElement("a");a.className="rc card "+cls;a.href=href;',
    ' var a=document.createElement("a");a.className="lr "+cls;a.href=href;')
rep('var b=document.createElement("b"),s=document.createElement("span");b.textContent=title;s.textContent=meta;a.appendChild(b);a.appendChild(s);return a;',
    'var b=document.createElement("b"),s=document.createElement("span"),x=document.createElement("i");b.textContent=title;s.textContent=meta;x.setAttribute("aria-hidden","true");x.textContent="\\u2192";a.appendChild(b);a.appendChild(s);a.appendChild(x);return a;')

# proof CSS: replace the stats, pr, chip rules with the new ones
i, j = between('.stats{display:grid;', '.lgd i{width:8px;height:8px;border-radius:50%;display:inline-block}\n')
proof_css = '''.figs{display:grid;grid-template-columns:1.35fr .8fr 1.35fr .8fr;margin-top:40px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.fg{padding:26px 24px 28px;min-width:0}
.fg+.fg{border-left:1px solid var(--line)}
.fg .k{display:flex;align-items:center;gap:7px;margin-bottom:16px}
.fg .k .ic{width:15px;height:15px}
.fn{display:flex;gap:28px;flex-wrap:wrap}
.fn div{min-width:0}
.fn b{display:block;font-size:clamp(44px,5.4vw,68px);font-weight:700;letter-spacing:-.05em;line-height:.95;font-variant-numeric:tabular-nums}
.fn span{display:block;margin-top:8px;font-size:14px;color:var(--mut);line-height:1.3;max-width:12em}
.fn .g{color:var(--ok)}.fn .bl{color:var(--test)}.fn .v{color:var(--audit)}
.shelf-h{display:flex;align-items:center;gap:12px;margin-top:clamp(56px,7vw,88px)}
.shelf-h h3{display:flex;align-items:center;gap:10px;font-size:22px;letter-spacing:-.025em}
.shelf-h h3 .ic{color:var(--test)}
.arws{margin-left:auto;display:flex;gap:8px}
.arw{width:42px;height:42px;min-height:0;padding:0;border-radius:50%;font-size:22px;line-height:1;color:var(--ink);background:var(--panel);border:1px solid var(--line);box-shadow:var(--lift)}
.arw:hover{background:var(--hover)}
.arw:disabled{opacity:.35;cursor:default}
.shelf{display:flex;gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;scroll-padding:0 24px;padding:20px 24px 36px;margin:0 -24px;scrollbar-width:none;outline:0}
.shelf::-webkit-scrollbar{display:none}
.pr{flex:0 0 min(400px,82vw);scroll-snap-align:start;display:flex;flex-direction:column;overflow:hidden;min-width:0}
.pr .shot{display:block;aspect-ratio:16/9;overflow:hidden;background:var(--sunk);border-bottom:1px solid var(--line)}
.pr .shot img{width:100%;height:100%;object-fit:cover;object-position:top left;display:block;transition:transform .8s var(--ease)}
.pr:hover .shot img{transform:scale(1.03)}
