 var els=document.querySelectorAll(".rv");
 if(rm||!("IntersectionObserver" in window)){Array.prototype.forEach.call(els,function(e){e.classList.add("in")});return}
 var io=new IntersectionObserver(function(en){en.forEach(function(e){if(e.isIntersecting){e.target.classList.add("in");io.unobserve(e.target);
  e.target.addEventListener("transitionend",function(){e.target.style.transitionDelay=""},{once:true})}})},{rootMargin:"0px 0px -8% 0px",threshold:.05});
